// План: specs/ui-style.md, тест 1.1. Тикет #ceb80d (עבר QA 17.11.2026). Только просмотр → @prod-safe.
import type { Page } from '@playwright/test';
import { test, expect } from '../../fixtures';

const TILES = ['ארנקי ילדים', 'ארנקים משותפים'];

type TileInfo = {
  error?: string;
  tile?: { x: number; y: number; w: number; h: number };
  title?: { x: number; y: number; w: number; h: number };
  icon?: { y: number; h: number; kind: string } | null;
  outside?: string[];
};

/** Плитка по заголовку: наибольший предок, не содержащий заголовок соседней плитки. */
async function inspectTile(page: Page, title: string, other: string): Promise<TileInfo> {
  return page.evaluate(
    ({ title, other }) => {
      const norm = (s: string | null) => (s || '').replace(/\s+/g, ' ').trim();
      const box = (e: Element) => {
        const r = e.getBoundingClientRect();
        return { x: r.x, y: r.y, w: r.width, h: r.height };
      };
      const leaves = Array.from(document.body.querySelectorAll('*')).filter((e) => e.children.length === 0);
      const titleEl = leaves.find((e) => norm(e.textContent) === title);
      if (!titleEl) return { error: 'нет заголовка «' + title + '»' };
      let tile: Element = titleEl;
      while (tile.parentElement && tile.parentElement !== document.body) {
        const p = tile.parentElement;
        if (norm(p.textContent).includes(other)) break;
        tile = p;
      }
      const emoji = /\p{Extended_Pictographic}/u;
      const tb = box(titleEl);
      let icon: TileInfo['icon'] = null;
      for (const e of Array.from(tile.querySelectorAll('*'))) {
        const tag = e.tagName.toLowerCase();
        const r = box(e);
        if (r.w === 0 || r.h === 0) continue;
        let kind = '';
        if (tag === 'img' || tag === 'svg') kind = tag;
        else if (e.children.length === 0 && e !== titleEl && emoji.test(e.textContent || '')) kind = 'emoji';
        if (kind) { icon = { y: r.y, h: r.h, kind }; break; }
      }
      const tr = box(tile);
      const outside: string[] = [];
      for (const e of Array.from(tile.querySelectorAll('*'))) {
        if (e.children.length || !norm(e.textContent)) continue;
        const r = box(e);
        if (r.x < tr.x - 1 || r.y < tr.y - 1 || r.x + r.w > tr.x + tr.w + 1 || r.y + r.h > tr.y + tr.h + 1) {
          outside.push(norm(e.textContent));
        }
      }
      return { tile: tr, title: tb, icon, outside };
    },
    { title, other },
  );
}

test.describe('מסך הבית — ארנקים נוספים', () => {
  test('ארנקים נוספים: אייקון מעל הכותרת באריחי «ארנקי ילדים» ו«ארנקים משותפים», הכיתובים בתוך האריח @prod-safe #ceb80d', async ({ asUser }) => {
    const client = await asUser('client'); // 0500000004
    await client.goto('/wallet');
    await expect(client.getByText('היתרה שלך').first()).toBeVisible({ timeout: 30_000 });

    const section = client.getByText('ארנקים נוספים', { exact: true }).first();
    await section.scrollIntoViewIfNeeded();
    const first = client.getByText(TILES[0], { exact: true }).first();
    if (!(await first.isVisible())) await section.click(); // раздел может быть свёрнут
    for (const t of TILES) {
      const el = client.getByText(t, { exact: true }).first();
      await el.scrollIntoViewIfNeeded();
      await expect(el).toBeVisible({ timeout: 15_000 });
    }

    for (let i = 0; i < TILES.length; i++) {
      const name = TILES[i];
      const info = await inspectTile(client, name, TILES[1 - i]);
      expect(info.error, name).toBeUndefined();

      // Иконка (img / svg / emoji) есть и расположена над заголовком.
      expect(info.icon, `на плитке «${name}» нет иконки (img/svg/emoji)`).toBeTruthy();
      expect(info.icon!.y + info.icon!.h, `иконка плитки «${name}» не над заголовком`).toBeLessThanOrEqual(info.title!.y + 2);

      // Все подписи плитки внутри плитки.
      expect(info.outside, `подписи плитки «${name}» выходят за её границы`).toEqual([]);
    }
  });
});
